questions.q:
Given this tickets array, what does `getUnassignedCriticalNumbers(tickets)` return?

var tickets = [
  { number: "INC001", priority: 1, assigned: false },
  { number: "INC002", priority: 1, assigned: true },
  { number: "INC003", priority: 2, assigned: false },
];
function getUnassignedCriticalNumbers(ticketList) {
  return ticketList
    .filter(function (t) { return t.priority === 1 && t.assigned === false; })
    .map(function (t) { return t.number; });
}
